svg.script:
(() => {
  "use strict";
  const NS = "http://www.w3.org/2000/svg";
  const CELL = 27, GAP = 12, RESULT_RIGHT = 562, INPUT_LEFT = 655, BIT_Y = 370;
  let value = 0xCA;
  let shift = 2;
  const byId = id => document.getElementById(id);
  const make = (type, attributes, text) => {
    const element = document.createElementNS(NS, type);
    for (const [name, entry] of Object.entries(attributes)) element.setAttribute(name, String(entry));
    if (text !== undefined) element.textContent = text;
    return element;
  };
  const bitWidth = n => n * CELL + Math.floor((n - 1) / 4) * GAP;
  function highlightText(textId, backgroundId, horizontalPadding = 8, verticalPadding = 5) {
    const rect = byId(backgroundId);
    const bbox = byId(textId).getBBox();
    rect.setAttribute("x", bbox.x - horizontalPadding);
    rect.setAttribute("y", bbox.y - verticalPadding);
    rect.setAttribute("width", bbox.width + 2 * horizontalPadding);
    rect.setAttribute("height", bbox.height + 2 * verticalPadding);
  }
  const updateHighlights = () => {
    // Nur eigenständige SVG-<text>-Elemente messen, keine <tspan>-Elemente.
    // Der Prefix besitzt xml:space="preserve", damit das abschließende Leerzeichen zählt.
    const codePrefix = byId("code-result-prefix");
    byId("code-result").setAttribute("x", Number(codePrefix.getAttribute("x")) + codePrefix.getComputedTextLength() + 9);
    const mathPrefix = byId("math-byte-prefix");
    byId("math-byte").setAttribute("x", Number(mathPrefix.getAttribute("x")) + mathPrefix.getComputedTextLength() + 9);
    highlightText("code-result", "code-result-highlight");
    highlightText("math-byte", "math-byte-highlight", 6, 5);
  };
  const toHex = number => `0x${number.toString(16).toUpperCase().padStart(2, "0")}`;

  function renderBits(container, bitString, startX, isResult) {
    container.replaceChildren();
    let gapOffset = 0;
    const n = bitString.length;
    for (let i = 0; i < n; i++) {
      if (i > 0 && (n - i) % 4 === 0) gapOffset += GAP;
      const x = startX + i * CELL + gapOffset + CELL / 2;
      let clazz = "diagram-a";
      if (isResult) clazz = i < shift ? "diagram-bit-lost" : i >= 8 ? "diagram-bit-new" : "diagram-bit-old";
      const bit = make("text", {
        x, y: BIT_Y, "text-anchor": "middle", class: `bit-text ${clazz}`
      }, bitString[i]);
      if (isResult) {
        container.appendChild(bit);
        if (i < shift) container.appendChild(make("line", {
          x1: x - 10, x2: x + 10, y1: BIT_Y - 14, y2: BIT_Y - 14, class: "diagram-strike"
        }));
      } else {
        const pos = 7 - i;
        const group = make("g", {
          class: "diagram-click-bit", role: "button", tabindex: "0", "data-bit": i,
          "aria-label": `Bit ${pos}: ${bitString[i]}; klicken zum Umschalten`
        });
        group.appendChild(make("title", {}, `Bit ${pos} umschalten`));
        group.appendChild(make("rect", {x: x - 13, y: BIT_Y - 39, width: 26, height: 51, rx: 6, ry: 6}));
        group.appendChild(bit);
        group.addEventListener("click", () => {
          value ^= (1 << pos);
          render();
        });
        group.addEventListener("keydown", evt => {
          if (evt.key === "Enter" || evt.key === " ") {
            evt.preventDefault();
            value ^= (1 << pos);
            render();
          }
        });
        container.appendChild(group);
      }
    }
  }

  function render() {
    const bits = value.toString(2).padStart(8, "0");
    const shifted = bits + "0".repeat(shift);
    const shiftedValue = value * 2 ** shift;
    const byte = shiftedValue & 0xFF;
    const lostOnes = (shiftedValue >>> 8) !== 0;
    const resultStart = RESULT_RIGHT - bitWidth(8 + shift);

    renderBits(byId("result-bits"), shifted, resultStart, true);
    renderBits(byId("input-bits"), bits, INPUT_LEFT, false);
    byId("result-heading").setAttribute("x", resultStart + bitWidth(8 + shift) / 2);
    // Genau die rechten acht Bits markieren, unabhängig vom Shift.
    const byteHighlight = byId("byte-bits-highlight");
    byteHighlight.setAttribute("x", RESULT_RIGHT - bitWidth(8) - 8);
    byteHighlight.setAttribute("width", bitWidth(8) + 16);
    byId("code-input").textContent = toHex(value);
    byId("code-shift").textContent = String(shift);
    byId("code-result").textContent = toHex(byte);
    byId("shift-value").textContent = String(shift);
    byId("shift-control").setAttribute("aria-label", `Shift ${shift}. Klick erhöht, Shift-Klick verringert`);
    byId("math-input").textContent = String(value);
    byId("math-exponent").textContent = String(shift);
    byId("math-result").textContent = String(shiftedValue);
    byId("math-byte").textContent = String(byte);
    updateHighlights();
    const note = byId("math-note");
    note.textContent = lostOnes
      ? "Oben gehen gesetzte Bits verloren; im uint8_t bleiben nur die unteren 8 Bits."
      : "Keine 1 geht verloren: Das uint8_t-Ergebnis entspricht der Multiplikation.";
  }

  const control = byId("shift-control");
  const changeShift = evt => {
    const amount = evt.shiftKey ? -1 : 1;
    shift = Math.max(0, Math.min(8, shift + amount));
    render();
  };
  control.addEventListener("click", changeShift);
  control.addEventListener("keydown", evt => {
    if (evt.key === "Enter" || evt.key === " ") {
      evt.preventDefault();
      changeShift(evt);
    }
  });
  render();
  // Font-Dateien können erst nach dem initialen Rendern geladen sein.
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(updateHighlights);
})();
